INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Landmine_180s', 'Landmine 180''s', 'core', ARRAY['legs','back','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position. Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise. Reverse the motion to swing the weight all the way to the opposite'),
('Landmine_Linear_Jammer', 'Landmine Linear Jammer', 'shoulders', ARRAY['core','legs','chest','legs','legs','arms']::text[], 'barbell', 'strength', 'intermediate', 'Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar. Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position. In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed. Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten th'),
('Lateral_Bound', 'Lateral Bound', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position. Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg. Immediately push off and extend, attempting to bound to the side as far as possible. Upon landing, immediately push off in the opposite direction, returning to your original start position. Continue back and forth for several repetitions.'),
('Lateral_Box_Jump', 'Lateral Box Jump', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position. Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side. Bring your knees high enough to ensure your feet have good clearance over the box. Land on the center of the box, using your legs to absorb the impact. Carefully jump down to the other side of the box, and continue going back and forth for several repetit'),
('Lateral_Cone_Hops', 'Lateral Cone Hops', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Position a number of cones in a row several feet apart. Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position. Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.'),
('Lateral_Raise_-_With_Bands', 'Lateral Raise - With Bands', 'shoulders', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are sligh'),
('Latissimus_Dorsi-SMR', 'Latissimus Dorsi-SMR', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position. Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.'),
('Leg-Over_Floor_Press', 'Leg-Over Floor Press', 'chest', ARRAY['shoulders','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support. Press the kettlebll into a locked out position. Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.'),
('Leg-Up_Hamstring_Stretch', 'Leg-Up Hamstring Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine. Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it). Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.'),
('Leg_Extensions', 'Leg Extensions', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over th'),
('Leg_Lift', 'Leg Lift', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance. With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement. Slowly bring the raised leg back to the floor as you breathe in. Repeat for the recommended amount of repetitions. Rep'),
('Leg_Press', 'Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully exten'),
('Leg_Pull-In', 'Leg Pull-In', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should alwa'),
('Leverage_Chest_Press', 'Leverage Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until th'),
('Leverage_Deadlift', 'Leverage Deadlift', 'legs', ARRAY['legs','legs']::text[], 'machine', 'strength', 'beginner', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position. Return the weight to the starting position.'),
('Leverage_Decline_Chest_Press', 'Leverage Decline Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is c'),
('Leverage_High_Row', 'Leverage High Row', 'back', ARRAY['back']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the sto'),
('Leverage_Incline_Chest_Press', 'Leverage Incline Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is comp'),
('Leverage_Iso_Row', 'Leverage Iso Row', 'back', ARRAY['arms','back']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles b'),
('Leverage_Shoulder_Press', 'Leverage Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position. Press the handles upward by extending through the elbow. After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is'),
('Leverage_Shrug', 'Leverage Shrug', 'back', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position. Raise the weight by shrugging the sho'),
('Linear_3-Part_Start_Technique', 'Linear 3-Part Start Technique', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left. Place your right hand onto the line, and thing bring your nose close to your left knee. Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting positio'),
('Linear_Acceleration_Wall_Drill', 'Linear Acceleration Wall Drill', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted. Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground. Switch legs, raising the opposite knee, and then attacking the ground straight down. Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.'),
('Linear_Depth_Jump', 'Linear Depth Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'intermediate', 'You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform. To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex. Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform. Land softly, asborbing the impact through the legs.'),
('Log_Lift', 'Log Lift', 'shoulders', ARRAY['core','chest','legs','legs','back','back','legs','back','arms']::text[], 'other', 'strongman', 'intermediate', 'Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean. Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the l'),
('London_Bridges', 'London Bridges', 'back', ARRAY['arms','arms','back']::text[], 'other', 'strength', 'intermediate', 'Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized. Stand on the bar, using the rope to balance yourself. This will be your starting position. Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground. Keeping your body straight, reverse the motion, '),
('Looking_At_Ceiling', 'Looking At Ceiling', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Kneel on the floor, holding your heels with both hands. Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.'),
('Low_Cable_Crossover', 'Low Cable Crossover', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand. Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position. With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up. Return your arms back to t'),
('Low_Cable_Triceps_Extension', 'Low Cable Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment. Grab the outside of the rope ends with your palms facing each other (neutral grip). Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards'),
('Low_Pulley_Row_To_Neck', 'Low Pulley Row To Neck', 'shoulders', ARRAY['arms','back','back']::text[], 'cable', 'strength', 'beginner', 'Sit on a low pulley row machine with a rope attachment. Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position. While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the '),
('Lower_Back-SMR', 'Lower Back-SMR', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position. Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.'),
('Lower_Back_Curl', 'Lower Back Curl', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Lie on your stomach with your arms out to your sides. This will be your starting position. Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions.'),
('Lunge_Pass_Through', 'Lunge Pass Through', 'legs', ARRAY['legs','legs','legs']::text[], 'kettlebell', 'strength', 'intermediate', 'Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position. Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground. As you lunge, pass the kettlebell under your front leg to your opposite hand. Pressing through the heel of your foot, return to the starting position. Repeat the movement for the recommended amount of repetition'),
('Lunge_Sprint', 'Lunge Sprint', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position. Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so. At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from you'),
('Lying_Bent_Leg_Groin', 'Lying Bent Leg Groin', 'legs', ARRAY[]::text[], 'other', 'stretching', 'expert', 'Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position. Attempt to squeeze your knees together, while your partner prevents any movement from occurring. After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.'),
('Lying_Cable_Curl', 'Lying Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip. Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight. With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position. While keeping your upper arms stationary and the elbows close to y'),
('Lying_Cambered_Barbell_Row', 'Lying Cambered Barbell Row', 'back', ARRAY['arms','back','back']::text[], 'barbell', 'strength', 'beginner', 'Place a cambered bar underneath an exercise bench. Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position. As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. After a second hold at the top, lower back down to the starting position slowly as you inhale.'),
('Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Place a flat bench in front of a high pulley or lat pulldown machine. Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width. Lie on your back with your head over the end of the bench. Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position. As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze t'),
('Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead'),
('Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position. As you inhale, lower the bar in a'),
('Lying_Crossover', 'Lying Crossover', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'expert', 'Lie on your back with your legs extended. Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position. Attempt to raise the bent knee off of the ground as your partner prevents any actual movement. After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with '),
('Lying_Dumbbell_Tricep_Extension', 'Lying Dumbbell Tricep Extension', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position. As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears. At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring th'),
('Lying_Face_Down_Plate_Neck_Resistance', 'Lying Face Down Plate Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position. While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in. Raise your head back up to the starting position in a semi-circula'),
('Lying_Face_Up_Plate_Neck_Resistance', 'Lying Face Up Plate Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position. While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in. Raise your head back up to the starting position in a semi-circul'),
('Lying_Glute', 'Lying Glute', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'expert', 'Lie on your back with your partner kneeling beside you. Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position. Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg. After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your '),
('Lying_Hamstring', 'Lying Hamstring', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'expert', 'Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position. With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds. Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper wh'),
('Lying_High_Bench_Barbell_Curl', 'Lying High Bench Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position. While keeping the elbows in and th'),
('Lying_Leg_Curls', 'Lying Leg Curls', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment. Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other'),
('Lying_Machine_Squat', 'Lying Machine Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel. Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly bel'),
('Lying_One-Arm_Lateral_Raise', 'Lying One-Arm Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability. Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhal')
